  internal async Task LoadMap(){int request=++mapVersion;if(Result==null||ChartChoice.SelectedIndex!=2)return;if(GroupChoice.SelectedIndex!=0){Chart.MapRows=Chart.Rows;return;}var result=Result;var folder=selected??result.Root;var map=new List<DiskChartRow>();foreach(var child in folder.Children.Where(x=>MetricChoice.SelectedIndex==1?x.Files>0:x.Bytes>0).OrderByDescending(x=>MetricChoice.SelectedIndex==1?x.Files:x.Bytes).Take(512)){map.Add(new DiskChartRow{Key=child.Path,TargetPath=child.Path,Name=child.Name,Bytes=child.Bytes,Files=child.Files,Value=MetricChoice.SelectedIndex==1?child.Files:child.Bytes,Color=DiskChart.ColorFor(child.Path)});}long hiddenBytes=folder.Children.Sum(x=>x.Bytes)-map.Sum(x=>x.Bytes),hiddenFiles=folder.Children.Sum(x=>x.Files)-map.Sum(x=>x.Files);if(hiddenBytes>0||hiddenFiles>0){var visibleFolders=new HashSet<string>(map.Select(x=>x.TargetPath),StringComparer.OrdinalIgnoreCase);var hiddenFolders=folder.Children.Where(x=>!visibleFolders.Contains(x.Path)).Select(x=>x.Path).ToArray();map.Add(new DiskChartRow{Key="__otherFolders",Name=L.Text("analyzer.other"),Predicate=file=>hiddenFolders.Any(root=>DiskFileIndex.Within(file.Path,root)),Bytes=hiddenBytes,Files=hiddenFiles,Value=MetricChoice.SelectedIndex==1?hiddenFiles:hiddenBytes,Color=FluentTheme.Muted});}if(result.IndexPath!=null&&!folder.Virtual){try{long total=0;var rows=await Task.Run(()=>DiskFileIndex.Page(result.IndexPath,file=>String.Equals(Path.GetDirectoryName(file.Path).TrimEnd('\\'),folder.Path.TrimEnd('\\'),StringComparison.OrdinalIgnoreCase),0,1024,CancellationToken.None,out total));if(request!=mapVersion||closed)return;foreach(var file in rows)map.Add(new DiskChartRow{Key=file.Path,TargetPath=file.Path,TargetFile=true,Name=Path.GetFileName(file.Path),Bytes=file.Bytes,Files=1,Value=MetricChoice.SelectedIndex==1?1:file.Bytes,Color=DiskChart.ColorFor(Path.GetExtension(file.Path))});long bytes=folder.DirectBytes-rows.Sum(x=>x.Bytes),count=folder.DirectFiles-rows.Count;if(bytes>0||cou